import re

_NUM = r"(?:0|[1-9]\d*)"
_IDENT = r"(?:0|[1-9]\d*|[0-9A-Za-z-]*[A-Za-z-][0-9A-Za-z-]*)"
_VERSION_PATTERN = (
    rf"(?P<major>{_NUM})\.(?P<minor>{_NUM})\.(?P<patch>{_NUM})"
    rf"(?:-(?P<prerelease>{_IDENT}(?:\.{_IDENT})*))?"
)
_VERSION_RE = re.compile(_VERSION_PATTERN)
_COMPARATOR_RE = re.compile(rf"(?P<op>>=|<=|=|>|<|\^|~)?{_VERSION_PATTERN}")


def _parse_version(value):
    if not isinstance(value, str):
        raise ValueError("version must be a string")

    match = _VERSION_RE.fullmatch(value)
    if match is None:
        raise ValueError(f"invalid version: {value!r}")

    major = int(match.group("major"))
    minor = int(match.group("minor"))
    patch = int(match.group("patch"))
    prerelease = match.group("prerelease")
    prerelease_ids = tuple(prerelease.split(".")) if prerelease is not None else None

    return (major, minor, patch, prerelease_ids)


def _is_numeric_identifier(identifier):
    return identifier.isdigit()


def _compare_prerelease(left, right):
    if left is None and right is None:
        return 0
    if left is None:
        return 1
    if right is None:
        return -1

    for left_id, right_id in zip(left, right):
        left_numeric = _is_numeric_identifier(left_id)
        right_numeric = _is_numeric_identifier(right_id)

        if left_numeric and right_numeric:
            left_value = int(left_id)
            right_value = int(right_id)
            if left_value != right_value:
                return -1 if left_value < right_value else 1
        elif left_numeric:
            return -1
        elif right_numeric:
            return 1
        else:
            if left_id != right_id:
                return -1 if left_id < right_id else 1

    if len(left) != len(right):
        return -1 if len(left) < len(right) else 1
    return 0


def _compare_versions(left, right):
    left_major, left_minor, left_patch, left_prerelease = left
    right_major, right_minor, right_patch, right_prerelease = right

    if (left_major, left_minor, left_patch) != (right_major, right_minor, right_patch):
        return -1 if (left_major, left_minor, left_patch) < (right_major, right_minor, right_patch) else 1

    return _compare_prerelease(left_prerelease, right_prerelease)


def _parse_comparator(token):
    if not isinstance(token, str):
        raise ValueError("comparator must be a string")

    match = _COMPARATOR_RE.fullmatch(token)
    if match is None:
        raise ValueError(f"invalid comparator: {token!r}")

    op = match.group("op") or "="
    version = (
        int(match.group("major")),
        int(match.group("minor")),
        int(match.group("patch")),
        tuple(match.group("prerelease").split(".")) if match.group("prerelease") is not None else None,
    )

    return op, version


def _parse_range(rng):
    if not isinstance(rng, str):
        raise ValueError("range must be a string")

    sets = []
    for part in rng.split("||"):
        comparators = []
        for token in part.split():
            comparators.append(_parse_comparator(token))

        if not comparators:
            raise ValueError(f"invalid range: empty comparator set in {rng!r}")

        sets.append(comparators)

    if not sets:
        raise ValueError(f"invalid range: {rng!r}")

    return sets


def _upper_bound_for_caret(version):
    major, minor, patch, _ = version
    if major > 0:
        return (major + 1, 0, 0, None)
    if minor > 0:
        return (0, minor + 1, 0, None)
    return (0, 0, patch + 1, None)


def _upper_bound_for_tilde(version):
    major, minor, _, _ = version
    return (major, minor + 1, 0, None)


def _satisfies_comparator(version, op, comparator_version):
    comparison = _compare_versions(version, comparator_version)

    if op == "=":
        return comparison == 0
    if op == ">":
        return comparison > 0
    if op == ">=":
        return comparison >= 0
    if op == "<":
        return comparison < 0
    if op == "<=":
        return comparison <= 0
    if op == "^":
        return comparison >= 0 and _compare_versions(version, _upper_bound_for_caret(comparator_version)) < 0
    if op == "~":
        return comparison >= 0 and _compare_versions(version, _upper_bound_for_tilde(comparator_version)) < 0

    raise ValueError(f"unknown operator: {op!r}")


def _satisfies_set(version, comparators):
    if version[3] is not None:
        allowed_by_prerelease = any(
            comparator_version[3] is not None
            and comparator_version[:3] == version[:3]
            for _, comparator_version in comparators
        )
        if not allowed_by_prerelease:
            return False

    return all(_satisfies_comparator(version, op, comparator_version) for op, comparator_version in comparators)


def satisfies(version, rng):
    parsed_version = _parse_version(version)
    parsed_range = _parse_range(rng)

    return any(_satisfies_set(parsed_version, comparator_set) for comparator_set in parsed_range)
