from datetime import datetime, timedelta


def _parse_field(field, min_value, max_value):
    values = set()
    for item in field.split(","):
        if not item:
            raise ValueError("empty item in cron field")

        if "/" in item:
            base, step_text = item.split("/", 1)
            if not step_text.isdigit():
                raise ValueError("invalid step in cron field")
            step = int(step_text)
            if step < 1:
                raise ValueError("step must be >= 1")
        else:
            base = item
            step = 1

        if base == "*":
            start = min_value
            end = max_value
        elif "-" in base:
            left, right = base.split("-", 1)
            if not left.isdigit() or not right.isdigit():
                raise ValueError("invalid range in cron field")
            start = int(left)
            end = int(right)
            if start > end:
                raise ValueError("range start must be <= range end")
        else:
            if not base.isdigit():
                raise ValueError("invalid value in cron field")
            start = int(base)
            end = max_value if step != 1 else start

        if start < min_value or start > max_value or end < min_value or end > max_value:
            raise ValueError("value out of range in cron field")

        values.update(range(start, end + 1, step))

    return values


def _cron_dow_to_python_dow(value):
    return (value - 1) % 7


def _earliest_time_on_day(day, minutes, hours, start_time):
    for hour in sorted(hours):
        if hour < start_time.hour:
            continue
        for minute in sorted(minutes):
            if hour == start_time.hour and minute < start_time.minute:
                continue
            return datetime(day.year, day.month, day.day, hour, minute)
    return None


def next_fire(expr, after):
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("cron expression must have exactly 5 fields")

    minute_field, hour_field, dom_field, month_field, dow_field = fields

    minutes = _parse_field(minute_field, 0, 59)
    hours = _parse_field(hour_field, 0, 23)
    doms = _parse_field(dom_field, 1, 31)
    months = _parse_field(month_field, 1, 12)
    dows = {_cron_dow_to_python_dow(value) for value in _parse_field(dow_field, 0, 7)}

    dom_restricted = dom_field != "*"
    dow_restricted = dow_field != "*"

    start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    limit = after + timedelta(days=3000)

    day = start.date()
    last_day = limit.date()

    while day <= last_day:
        if day.month in months:
            dom_match = day.day in doms
            dow_match = day.weekday() in dows

            if dom_restricted and dow_restricted:
                day_matches = dom_match or dow_match
            else:
                day_matches = (not dom_restricted or dom_match) and (not dow_restricted or dow_match)

            if day_matches:
                if day == start.date():
                    start_time = start
                else:
                    start_time = datetime(day.year, day.month, day.day)

                candidate = _earliest_time_on_day(day, minutes, hours, start_time)
                if candidate is not None and candidate <= limit:
                    return candidate

        day += timedelta(days=1)

    raise ValueError("no matching datetime within 3000 days")
