import copy


class PatchError(ValueError):
    pass


def apply_patch(doc, ops):
    """Apply a JSON Patch (RFC 6902 subset) to `doc` and return the resulting NEW document.

    `doc` and `ops` must never be modified, and the result must share no mutable object (dict/list) with either.
    The patch is all-or-nothing: on any error, raise PatchError.

    `ops` is a list of dicts. Each has "op" (one of add, remove, replace, move, copy, test) and "path";
    add/replace/test also need "value" (which may be None); move/copy also need "from". Missing keys are errors.

    Paths are JSON Pointers: "" is the whole document; otherwise "/" followed by "/"-separated tokens in which
    "~1" stands for "/" and "~0" for "~" ("~01" is the key "~1"). A "~" not followed by 0 or 1 is an error.
    A token addressing a list must be a base-10 index without leading zeros ("0" is fine). "-" means "past the
    end of the list" and is only allowed as the final token of an add (or of the target of move/copy).

    add:     object -> set the member (replacing any existing value); list -> insert BEFORE the index
             (index == len appends, index > len is an error). Adding at "" replaces the whole document.
             The parent container must exist.
    remove:  the target must exist. Removing "" is an error.
    replace: the target must exist. Replacing "" replaces the whole document.
    move:    remove the value at "from", then add it at "path". It is an error if "path" lies strictly inside
             "from" (a proper descendant). from == path is a no-op, but "from" must still exist.
    copy:    add a deep copy of the value at "from" at "path".
    test:    the target must exist and equal "value". Equality is JSON equality: numbers by value (1 == 1.0),
             booleans are never equal to numbers, objects by keys and values, lists elementwise.
    """
    if not isinstance(ops, list):
        raise PatchError("ops must be a list")

    result = _deep_copy(doc)

    for op in ops:
        if not isinstance(op, dict):
            raise PatchError("each operation must be a dict")

        op_name = op.get("op")
        if op_name not in {"add", "remove", "replace", "move", "copy", "test"}:
            raise PatchError("unknown or missing op")

        if "path" not in op:
            raise PatchError("missing path")
        path = op["path"]
        if not isinstance(path, str):
            raise PatchError("path must be a string")
        path_tokens = _parse_pointer(path)

        if op_name == "add":
            if "value" not in op:
                raise PatchError("add requires value")
            value = _deep_copy(op["value"])
            _add(result, path_tokens, value)

        elif op_name == "remove":
            _remove(result, path_tokens)

        elif op_name == "replace":
            if "value" not in op:
                raise PatchError("replace requires value")
            value = _deep_copy(op["value"])
            _replace(result, path_tokens, value)

        elif op_name == "move":
            if "from" not in op:
                raise PatchError("move requires from")
            from_path = op["from"]
            if not isinstance(from_path, str):
                raise PatchError("from must be a string")
            from_tokens = _parse_pointer(from_path)

            if _is_proper_descendant(path_tokens, from_tokens):
                raise PatchError("move target is inside source")

            _get_existing(result, from_tokens)

            if path_tokens == from_tokens:
                continue

            value = _get_existing(result, from_tokens)
            _remove(result, from_tokens)
            _add(result, path_tokens, value)

        elif op_name == "copy":
            if "from" not in op:
                raise PatchError("copy requires from")
            from_path = op["from"]
            if not isinstance(from_path, str):
                raise PatchError("from must be a string")
            from_tokens = _parse_pointer(from_path)

            value = _deep_copy(_get_existing(result, from_tokens))
            _add(result, path_tokens, value)

        elif op_name == "test":
            if "value" not in op:
                raise PatchError("test requires value")
            actual = _get_existing(result, path_tokens)
            if not _json_equal(actual, op["value"]):
                raise PatchError("test failed")

    return result


def _parse_pointer(pointer):
    if pointer == "":
        return []

    if not pointer.startswith("/"):
        raise PatchError("invalid pointer")

    tokens = []
    for raw_token in pointer[1:].split("/"):
        token = []
        i = 0
        while i < len(raw_token):
            ch = raw_token[i]
            if ch == "~":
                if i + 1 >= len(raw_token):
                    raise PatchError("invalid escape in pointer token")
                esc = raw_token[i + 1]
                if esc == "0":
                    token.append("~")
                elif esc == "1":
                    token.append("/")
                else:
                    raise PatchError("invalid escape in pointer token")
                i += 2
            else:
                token.append(ch)
                i += 1
        tokens.append("".join(token))

    return tokens


def _is_proper_descendant(path_tokens, from_tokens):
    if len(path_tokens) <= len(from_tokens):
        return False
    return path_tokens[:len(from_tokens)] == from_tokens


def _deep_copy(value):
    if isinstance(value, dict):
        return {key: _deep_copy(val) for key, val in value.items()}
    if isinstance(value, list):
        return [_deep_copy(item) for item in value]
    return copy.deepcopy(value)


def _get_parent(container, tokens):
    current = container
    for token in tokens:
        if isinstance(current, dict):
            if token not in current:
                raise PatchError("parent path does not exist")
            current = current[token]
        elif isinstance(current, list):
            index = _parse_list_index(token, len(current), allow_dash=False, allow_append=False)
            current = current[index]
        else:
            raise PatchError("cannot traverse into non-container")
    return current


def _get_existing(container, tokens):
    if not tokens:
        return container

    parent = _get_parent(container, tokens[:-1])
    token = tokens[-1]

    if isinstance(parent, dict):
        if token not in parent:
            raise PatchError("target does not exist")
        return parent[token]

    if isinstance(parent, list):
        index = _parse_list_index(token, len(parent), allow_dash=False, allow_append=False)
        return parent[index]

    raise PatchError("target parent is not a container")


def _parse_list_index(token, length, allow_dash, allow_append):
    if token == "-":
        if allow_dash:
            return length
        raise PatchError("invalid list index")

    if not token:
        raise PatchError("invalid list index")

    if not token.isdigit():
        raise PatchError("invalid list index")

    if len(token) > 1 and token[0] == "0":
        raise PatchError("invalid list index with leading zero")

    index = int(token)

    if allow_append:
        if index > length:
            raise PatchError("list index out of range")
    else:
        if index >= length:
            raise PatchError("list index out of range")

    return index


def _add(container, tokens, value):
    if not tokens:
        return value

    parent = _get_parent(container, tokens[:-1])
    token = tokens[-1]

    if isinstance(parent, dict):
        parent[token] = value
        return container

    if isinstance(parent, list):
        index = _parse_list_index(token, len(parent), allow_dash=True, allow_append=True)
        parent.insert(index, value)
        return container

    raise PatchError("add target parent is not a container")


def _remove(container, tokens):
    if not tokens:
        raise PatchError("cannot remove whole document")

    parent = _get_parent(container, tokens[:-1])
    token = tokens[-1]

    if isinstance(parent, dict):
        if token not in parent:
            raise PatchError("remove target does not exist")
        del parent[token]
        return container

    if isinstance(parent, list):
        index = _parse_list_index(token, len(parent), allow_dash=False, allow_append=False)
        del parent[index]
        return container

    raise PatchError("remove target parent is not a container")


def _replace(container, tokens, value):
    if not tokens:
        return value

    parent = _get_parent(container, tokens[:-1])
    token = tokens[-1]

    if isinstance(parent, dict):
        if token not in parent:
            raise PatchError("replace target does not exist")
        parent[token] = value
        return container

    if isinstance(parent, list):
        index = _parse_list_index(token, len(parent), allow_dash=False, allow_append=False)
        parent[index] = value
        return container

    raise PatchError("replace target parent is not a container")


def _json_equal(a, b):
    if isinstance(a, bool) or isinstance(b, bool):
        if isinstance(a, bool) and isinstance(b, bool):
            return a is b
        return False

    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a == b

    if isinstance(a, dict) and isinstance(b, dict):
        if len(a) != len(b):
            return False
        for key, value in a.items():
            if key not in b:
                return False
            if not _json_equal(value, b[key]):
                return False
        return True

    if isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            return False
        return all(_json_equal(x, y) for x, y in zip(a, b))

    return a == b
